// What counts as shame-worthy, as plain functions of the data and the time,
// so they can be tested without GitHub or Discord. shame.mjs fetches the data
// and keeps the counter; nothing here reads the clock or the network.

export const HOUR = 60 * 60 * 1000;
export const DAY = 24 * HOUR;

export const BEHEMOTH_LINES = 1000;
export const REVIEW_WITHIN = DAY; // a requested reviewer has this long to review
export const AUTHOR_WITHIN = 2 * DAY; // an author has this long to act after a review
export const RESHAME_EVERY = DAY; // still overdue after that: shamed again this often

const TZ = "America/New_York"; // the team's timezone, not UTC

// What people get shamed for, as the website charts it. The ids are stored in
// metrics/shame.json and are what /shame sends, so don't rename one; the
// labels can change freely. /shame can pick any of them.
export const CATEGORIES = {
  reviews: "Reviews",
  follow_through: "Follow-through",
  pr_size: "PR size",
  sleep: "Sleep",
  meetings: "Meetings",
  deadlines: "Deadlines",
  broke_something: "Broke something",
  communication: "Communication",
  other: "Other",
};

// The category each automatic shame counts under.
export const TYPE_CATEGORY = {
  behemoth: "pr_size",
  late_night: "sleep",
  slow_review: "reviews",
  idle_author: "follow_through",
};

export const ENDORSEMENTS_NEEDED = 2; // teammates besides the shamer and the shamed
export const REASON_MAX = 300;

// Swagger docs are generated by `swag init`, so they don't count toward size.
export function isCountedFile(filename) {
  return !filename.startsWith("server/cmd/docs/");
}

export function prSize(files) {
  return files
    .filter((f) => isCountedFile(f.filename))
    .reduce((sum, f) => sum + f.additions + f.deletions, 0);
}

// Hour, minute and calendar date in Eastern time.
export function easternParts(date) {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat("en-US", {
      timeZone: TZ,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hourCycle: "h23",
    })
      .formatToParts(date)
      .map((p) => [p.type, p.value]),
  );
  return {
    hour: Number(parts.hour),
    minute: Number(parts.minute),
    date: `${parts.year}-${parts.month}-${parts.day}`,
  };
}

// 1am up to (not including) 5am Eastern.
export function isLateNight(date) {
  const { hour } = easternParts(date);
  return hour >= 1 && hour < 5;
}

export function clockTime(date) {
  const { hour, minute } = easternParts(date);
  const h12 = hour % 12 === 0 ? 12 : hour % 12;
  return `${h12}:${String(minute).padStart(2, "0")} ${hour < 12 ? "AM" : "PM"}`;
}

export function ordinal(n) {
  const tens = n % 100;
  if (tens >= 11 && tens <= 13) return `${n}th`;
  return `${n}${{ 1: "st", 2: "nd", 3: "rd" }[n % 10] ?? "th"}`;
}

const latest = (times) => times.reduce((a, b) => (a === null || b > a ? b : a), null);
const earliest = (times) => times.reduce((a, b) => (a === null || b < a ? b : a), null);

// pr: an open pull request, normalized by shame.mjs:
//   { number, author, createdAt, readyAt,
//     requested: [login],              users asked to review right now
//     requestedAt: { login: iso },     latest time each user was asked
//     reviews: [{ login, at, state }], human reviews, not the author's
//     authorActivity: [iso] }          the author's own comments and replies
// pushes: ISO times of pushes to the PR that this bot has seen.
//
// Who owes a review, and since when. A requested reviewer owes one from when
// they were (last) asked. Someone who already reviewed owes another from the
// first push after their latest review, since a push dismisses approvals on
// this repo's branches. Time while the PR was a draft doesn't count.
export function reviewDebts(pr, pushes) {
  const debts = [];
  const notBefore = (t) => (pr.readyAt > t ? pr.readyAt : t);

  for (const login of pr.requested) {
    const start = pr.requestedAt[login] ?? pr.createdAt;
    const reviewed = pr.reviews.some((r) => r.login === login);
    debts.push({ login, since: notBefore(start), rereview: reviewed });
  }

  const reviewers = [...new Set(pr.reviews.map((r) => r.login))];
  for (const login of reviewers) {
    if (pr.requested.includes(login)) continue;
    const lastReview = latest(pr.reviews.filter((r) => r.login === login).map((r) => r.at));
    const firstPush = earliest(pushes.filter((p) => p > lastReview));
    if (firstPush) debts.push({ login, since: notBefore(firstPush), rereview: true });
  }

  return debts;
}

// How many shame periods have passed: 0 before the deadline, 1 once it
// passes, 2 a RESHAME_EVERY later, and so on. Each period is shamed once.
function periodsOverdue(since, within, now) {
  const elapsed = now - new Date(since).getTime();
  if (elapsed < within) return 0;
  return Math.floor((elapsed - within) / RESHAME_EVERY) + 1;
}

// Each returns shame candidates: { key, type, login, pr, ...details }.
// `key` is what stops the same shame being counted twice; it changes once
// per period, so an ongoing one is shamed again each period.

export function slowReviewShames(pr, pushes, now) {
  return reviewDebts(pr, pushes).flatMap((debt) => {
    const period = periodsOverdue(debt.since, REVIEW_WITHIN, now);
    if (period === 0) return [];
    return [{
      key: `slow_review:pr${pr.number}:${debt.login}:${debt.since}:${period}`,
      type: "slow_review",
      login: debt.login,
      pr: pr.number,
      rereview: debt.rereview,
      days: Math.floor((now - new Date(debt.since).getTime()) / DAY),
      period,
    }];
  });
}

// The author hasn't done anything since the latest review. Nobody owes a
// review then (or the ball would be in the reviewers' court), the author
// hasn't pushed, commented or replied since, and it's been AUTHOR_WITHIN.
export function idleAuthorShames(pr, pushes, now) {
  if (reviewDebts(pr, pushes).length > 0) return [];
  const lastReview = pr.reviews.reduce((a, r) => (a === null || r.at > a.at ? r : a), null);
  if (!lastReview) return [];
  const acted = [...pushes, ...pr.authorActivity].some((t) => t > lastReview.at);
  if (acted) return [];
  const period = periodsOverdue(lastReview.at, AUTHOR_WITHIN, now);
  if (period === 0) return [];
  return [{
    key: `idle_author:pr${pr.number}:${lastReview.at}:${period}`,
    type: "idle_author",
    login: pr.author,
    pr: pr.number,
    approved: lastReview.state === "APPROVED",
    hours: Math.floor((now - new Date(lastReview.at).getTime()) / HOUR),
    period,
  }];
}

export function behemothShame(pr, lines) {
  if (lines <= BEHEMOTH_LINES) return [];
  return [{ key: `behemoth:pr${pr.number}`, type: "behemoth", login: pr.author, pr: pr.number, lines }];
}

// One late-night shame per person per night, however much they do.
export function lateNightShame(login, at, action, prNumber) {
  const date = new Date(at);
  if (!isLateNight(date)) return [];
  return [{
    key: `late_night:${login}:${easternParts(date).date}`,
    type: "late_night",
    login,
    pr: prNumber,
    action,
    time: clockTime(date),
  }];
}

// A /shame that reached enough endorsements, sent by the team website as a
// repository_dispatch. People arrive as Discord user IDs and are turned back
// into GitHub logins with the same map the bot mentions people with, so only
// people on the team can shame, be shamed or endorse. Returns a candidate, or
// throws saying what's wrong.
//   { messageId, target, by, endorsedBy: [id], category, reason }
export function manualShame(payload, userMap, needed = ENDORSEMENTS_NEEDED) {
  const loginOf = Object.fromEntries(Object.entries(userMap).map(([login, id]) => [String(id), login]));
  const person = (id, role) => {
    const login = loginOf[String(id)];
    if (!login) throw new Error(`${role} (Discord user ${id}) isn't in DISCORD_USER_MAP`);
    return login;
  };
  if (!/^\d+$/.test(String(payload.messageId ?? ""))) throw new Error("messageId must be a Discord message ID");
  const login = person(payload.target, "The shamed person");
  const by = person(payload.by, "The shamer");
  if (!Object.hasOwn(CATEGORIES, payload.category)) throw new Error(`Unknown category "${payload.category}"`);
  const reason = String(payload.reason ?? "").trim();
  if (!reason) throw new Error("A shame needs a reason");
  if (reason.length > REASON_MAX) throw new Error(`The reason is over ${REASON_MAX} characters`);
  const endorsedBy = [...new Set((payload.endorsedBy ?? []).map((id) => person(id, "An endorser")))]
    .filter((e) => e !== login && e !== by);
  if (endorsedBy.length < needed) {
    throw new Error(`Needs ${needed} endorsements from teammates other than ${by} and ${login}, got ${endorsedBy.length}`);
  }
  return {
    key: `manual:${payload.messageId}`,
    type: "manual",
    category: payload.category,
    login,
    by,
    endorsedBy,
    reason,
  };
}

// Adds each candidate not already in state.shamed to the log. Returns the
// shames that are new, each with the person's total after it.
//
// The log (metrics/shame.json) is just what happened, one entry per shame;
// the website does the counting, like it does for metrics/pull-requests.json.
export function applyShames(state, log, candidates, nowIso) {
  const added = [];
  for (const c of candidates) {
    if (state.shamed[c.key]) continue;
    state.shamed[c.key] = nowIso;
    const entry = { at: nowIso, login: c.login, category: c.category ?? TYPE_CATEGORY[c.type], type: c.type };
    if (c.pr) entry.pr = c.pr;
    if (c.type === "manual") Object.assign(entry, { reason: c.reason, by: c.by, endorsedBy: c.endorsedBy });
    log.shames.push(entry);
    const total = log.shames.filter((s) => s.login === c.login).length;
    added.push({ ...c, category: entry.category, total });
  }
  return added;
}

export function emptyLog() {
  return { categories: CATEGORIES, shames: [] };
}

// Keys only need to outlive the period they're for; drop old ones.
export function pruneShamed(state, now, keepFor = 60 * DAY) {
  for (const [key, at] of Object.entries(state.shamed)) {
    if (now - new Date(at).getTime() > keepFor) delete state.shamed[key];
  }
}
